solution.code:
class Barang:
    def __init__(self, nama, harga):
        self.nama = nama
        self.harga = harga


class TanpaDiskon:
    def hitung(self, total):
        return total


class DiskonPersen:
    def __init__(self, persen):
        self.persen = persen

    def hitung(self, total):
        return total - total * self.persen // 100


class DiskonNominal:
    def __init__(self, nominal):
        self.nominal = nominal

    def hitung(self, total):
        return max(0, total - self.nominal)


def buat_diskon(kode):
    if kode == "TANPA":
        return TanpaDiskon()
    if kode[:1] in ("P", "N") and kode[1:].isdigit():
        angka = int(kode[1:])
        return DiskonPersen(angka) if kode[0] == "P" else DiskonNominal(angka)
    raise ValueError(f"kode diskon tidak dikenal: {kode}")


class Keranjang:
    def __init__(self, diskon=None):
        self.diskon = diskon or TanpaDiskon()
        self._baris = {}

    def tambah(self, barang, qty=1):
        if qty <= 0:
            raise ValueError("qty harus lebih dari 0")
        lama = self._baris.get(barang.nama)
        self._baris[barang.nama] = (barang, qty + (lama[1] if lama else 0))

    def total(self):
        return sum(b.harga * q for b, q in self._baris.values())

    def bayar(self):
        return self.diskon.hitung(self.total())

    def __len__(self):
        return len(self._baris)

    def jumlah_barang(self):
        return sum(q for _, q in self._baris.values())


class Kasir:
    def __init__(self):
        self.pendengar = []

    def daftar(self, f):
        self.pendengar.append(f)

    def checkout(self, keranjang):
        if len(keranjang) == 0:
            raise ValueError("keranjang kosong")
        struk = {"total": keranjang.bayar(), "jumlah": keranjang.jumlah_barang()}
        for f in self.pendengar:
            f(struk)
        return struk

