class Toko:
    def __init__(self):
        self.pendengar = []

    def daftar(self, f):
        self.pendengar.append(f)

    def berhenti(self, f):
        if f in self.pendengar:
            self.pendengar.remove(f)

    def jual(self, barang):
        for f in list(self.pendengar):
            f(barang)
        return len(self.pendengar)
